  /** 原稿を最後に編集した日。公開日・監修日とは別に管理する。 */
  updatedAt: string;
  readingMinutes: number;
  status: "draft" | "published";
  reviewer?: Reviewer;
  /** 実際に公開した日。予定日を代入せず、公開後に台帳へ記録する。 */
